import re

def clean_product_data(data):
    pattern = r'^(?P<id>\w+)\s*,\s*(?P<price>\d+(?:\.\d+)?)\s*,\s*(?P<category>Electronics|Clothing|Books)$'
    valid_rows = []
    for line in data.strip().split('\n'):
        m = re.match(pattern, line)
        if m:
            valid_rows.append({
                'id': m.group('id'),
                'price': float(m.group('price')),
                'category': m.group('category')
            })
    return valid_rows

