def find_repeated_words(text):
    pattern = r'____'
    matches = re.finditer(pattern, text, re.IGNORECASE)
    seen = {}
    for m in matches:
        w = m.group('word').lower()
        seen[w] = seen.get(w, 0) + 1
    return [(w, c) for w, c in seen.items() if c >= 2]

